package dev.irisvisualizer.editor;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;

final class ResourceBrowserTests {
    private static final ResourceBrowser.Query ALL=new ResourceBrowser.Query("",ResourceFinder.Family.ALL,false);
    private static final ResourceBrowser.Query CHANGED=new ResourceBrowser.Query("",ResourceFinder.Family.ALL,true);
    private static byte[] bytes(String text){return text.getBytes(StandardCharsets.UTF_8);}
    private static void check(boolean value,String message){if(!value)throw new AssertionError("Resource browser: "+message);}
    private static List<String> paths(ResourceBrowser.Page page){return page.rows().stream().map(ResourceBrowser.Row::path).toList();}
    private static void invalid(Runnable action){try{action.run();}catch(IllegalArgumentException expected){return;}throw new AssertionError("Expected invalid browser query");}
    static void run(Path temp) throws Exception {
        var files=new LinkedHashMap<String,byte[]>();var expected=new ArrayList<String>();expected.add("biomes");
        for(int i=0;i<650;i++){String path=String.format(Locale.ROOT,"biomes/pick_%04d.json",i);files.put(path,bytes("malformed target JSON 雪"));expected.add(path);}
        for(int i=0;i<235;i++)files.put(String.format(Locale.ROOT,"objects/nest_%03d/opaque.iob",i),new byte[]{0,-1,7});
        files.put("images/雪#dir/pixel.PNG",new byte[]{-1,0});files.put("A.json",bytes("{\"future\":9007199254740993}"));files.put("z.bin",new byte[]{0,1,-1});
        files.put("biomes/has space.json",bytes("not parsed"));files.put("biomes/[a-z]+.json",bytes("not parsed"));
        String deep="biomes/"+"a/".repeat(62)+"deep.json";files.put(deep,bytes("invalid at maximum depth"));
        var pack=PackWorkspace.newPack(files);String empty=pack.createSubfolder("biomes","empty");var cache=new ResourceBrowser.Cache();
        var drafts=new InspectorDrafts();drafts.update("unrelated","stored","typing");long applied=pack.revision(),structural=pack.resourceRevision(),saved=pack.saveRevision();int undo=pack.undoCount();
        var roots=cache.page(pack,ALL,0);check(paths(roots).equals(List.of("biomes","images","objects","A.json","z.bin")),"folder-first natural ordering and collapsed roots");check(roots==cache.page(pack,ALL,Integer.MAX_VALUE),"clamped page identity");
        check(cache.toggle(pack,ALL,"biomes"),"explicit expansion");var opened=cache.page(pack,ALL,0);check(opened.rows().getFirst().expanded() && paths(opened).subList(1,3).equals(List.of("biomes/a",empty)),"folders precede files within expanded sibling order");
        var query=new ResourceBrowser.Query("PICK_",ResourceFinder.Family.ALL,false);var first=cache.page(pack,query,-1);check(first.window().matches()==651 && first.window().pages()==4 && first.rows().size()==200,"global visible-row count includes matching ancestors and bounds total rows");
        var visited=new ArrayList<String>();for(int page=0;page<4;page++){var current=cache.page(pack,query,page);check(current.rows().size()<=200 && current.request()==first.request() && current==cache.page(pack,query,page),"single stable bounded page without a full visible-row copy");visited.addAll(paths(current));}
        check(visited.equals(expected) && new HashSet<>(visited).size()==expected.size(),"every visible row appears once across complete pages");var last=cache.page(pack,query,Integer.MAX_VALUE);check(last.window().page()==3 && last.rows().size()==51,"short last page and overflow clamping");
        check(!cache.toggle(pack,query,"biomes") && cache.page(pack,query,3)==last,"search keeps existing forced-open ancestor behavior");
        String late=expected.getLast();var revealed=cache.reveal(pack,ALL,late);check(paths(revealed).contains(late) && revealed.window().page()>0,"Reveal opens ancestors and finds the actual last-file page");
        String object="objects/nest_234/opaque.iob";check(paths(cache.reveal(pack,ALL,object)).contains(object),"Reveal crosses later root folders and nested sibling pages");
        var deepPage=cache.reveal(pack,ALL,deep);check(deepPage.rows().stream().anyMatch(row->row.path().equals(deep) && row.depth()==63),"maximum supported depth stays reachable");
        var beforeMissing=cache.page(pack,ALL,0);check(cache.reveal(pack,ALL,"missing/file.json")==null && cache.page(pack,ALL,0)==beforeMissing && !cache.toggle(pack,ALL,late),"missing/file expansion requests retain accepted layout");
        cache.collapseAll();check(paths(cache.page(pack,ALL,0)).equals(paths(roots)),"collapse releases expansion state without losing files");
        check(paths(cache.reveal(pack,ALL,empty)).contains(empty),"explicit empty folder remains reachable");
        var emptyQuery=new ResourceBrowser.Query("empty",ResourceFinder.Family.ALL,false);check(paths(cache.page(pack,emptyQuery,0)).equals(List.of("biomes",empty)),"matching empty folders keep ancestors in unfiltered family");
        check(cache.page(pack,new ResourceBrowser.Query("empty",ResourceFinder.Family.BIOMES,false),0).rows().isEmpty(),"family filters retain original empty-folder hiding policy");
        var objects=new ResourceBrowser.Query("opaque",ResourceFinder.Family.OBJECTS,false);int objectFiles=0;var objectFirst=cache.page(pack,objects,0);check(objectFirst.window().matches()==471,"all filtered folder/file rows counted");
        for(int page=0;page<objectFirst.window().pages();page++)for(var row:cache.page(pack,objects,page).rows())if(!row.folder()){check(ResourceFinder.Family.OBJECTS.matches(row.path()),"family eligibility");objectFiles++;}check(objectFiles==235,"all opaque assets reachable without decoding");
        check(paths(cache.page(pack,new ResourceBrowser.Query("has space",ResourceFinder.Family.ALL,false),0)).equals(List.of("biomes","biomes/has space.json")),"browser query is one literal substring, preserving spaces");
        check(paths(cache.page(pack,new ResourceBrowser.Query("[a-z]+",ResourceFinder.Family.ALL,false),0)).contains("biomes/[a-z]+.json"),"no regex interpretation");check(paths(cache.reveal(pack,ALL,"images/雪#dir/pixel.PNG")).contains("images/雪#dir/pixel.PNG"),"raw Unicode/hash/case preserved in metadata");
        cache.page(pack,new ResourceBrowser.Query("İ".repeat(256),ResourceFinder.Family.ALL,false),0);var accepted=cache.page(pack,ALL,0);
        for(String text:List.of("x".repeat(257),"a\u0000b","a\nb","a\tb"))invalid(()->new ResourceBrowser.Query(text,ResourceFinder.Family.ALL,false));invalid(()->new ResourceBrowser.Query(null,ResourceFinder.Family.ALL,false));check(cache.page(pack,ALL,0)==accepted,"invalid queries leave accepted cached metadata intact");
        check(pack.revision()==applied && pack.resourceRevision()==structural && pack.saveRevision()==saved && pack.undoCount()==undo && drafts.any(),"paging/reveal/filter/expansion never changes workspace/history/drafts");for(String path:files.keySet())check(Arrays.equals(pack.read(path),files.get(path)),"original malformed/unknown/opaque bytes preserved");
        // Structural changes preserve surviving implicit-folder expansion and remove stale folder paths.
        cache.reveal(pack,ALL,late);long generation=cache.page(pack,ALL,0).treeGeneration();String another=pack.createSubfolder("biomes","another");var rebuilt=cache.page(pack,ALL,0);check(rebuilt.treeGeneration()!=generation && rebuilt.rows().getFirst().expanded() && paths(rebuilt).contains(another),"resource revision rebuilds metadata while retaining implicit ancestor expansion");
        String renamed=pack.renameEmptyFolder(another,"renamed");check(cache.reveal(pack,ALL,another)==null && paths(cache.reveal(pack,ALL,renamed)).contains(renamed),"renamed folder metadata cannot reveal stale paths");pack.deleteEmptyFolder(renamed);check(cache.reveal(pack,ALL,renamed)==null,"deleted folder metadata is pruned");
        // Guarded Open remains separate from revealing a row or turning a page.
        var nav=new ResourceNavigation();nav.request(pack,late);var request=nav.takeRequest(pack);var selected=new AtomicReference<>("A.json");check(!drafts.transition(()->false,()->selected.set(request.target())) && selected.get().equals("A.json") && drafts.any(),"later-page draft cancellation does not open a target");check(paths(cache.reveal(pack,query,late)).contains(late) && selected.get().equals("A.json"),"Reveal remains read-only even after cancelled Open");
        check(drafts.transition(()->true,()->selected.set(request.target())) && selected.get().equals(late),"explicit guarded Open still selects the exact raw path");
        // Small disk fixtures exercise baseline changes, including partial Save with unchanged dirty/revision state.
        var small=PackWorkspace.newPack(Map.of("blocks/a.json",bytes("a"),"blocks/z.json",bytes("z"),"future/opaque.bin",new byte[]{0,-1}));Path root=temp.resolve("resource-browser-small");small.save(root);var smallCache=new ResourceBrowser.Cache();var json=new ResourceBrowser.Query(".json",ResourceFinder.Family.ALL,false);var clean=smallCache.page(small,json,0);check(clean.rows().stream().noneMatch(ResourceBrowser.Row::changed),"saved flags start clean");
        small.replace("blocks/a.json",bytes("A"));var edited=smallCache.page(small,json,0);check(edited!=clean && edited.treeGeneration()==clean.treeGeneration() && edited.rows().stream().anyMatch(row->row.path().equals("blocks/a.json") && row.changed()),"byte edits refresh row markers without rebuilding all-file tree");small.undo();check(smallCache.page(small,CHANGED,0).rows().isEmpty(),"Undo removes changed-only matches");small.redo();check(paths(smallCache.reveal(small,CHANGED,"blocks/a.json")).contains("blocks/a.json"),"Redo restores changed-only file and ancestors");
        var beforeSave=smallCache.page(small,json,0);small.save(root);var afterSave=smallCache.page(small,json,0);check(afterSave!=beforeSave && afterSave.treeGeneration()==beforeSave.treeGeneration() && afterSave.rows().stream().noneMatch(ResourceBrowser.Row::changed),"Save refreshes markers without rebuilding path-only tree");check(smallCache.page(small,CHANGED,0).rows().isEmpty(),"Save refreshes changed-only membership");
        small.replace("blocks/a.json",bytes("AA"));small.replace("blocks/z.json",bytes("ZZ"));var partialBefore=smallCache.reveal(small,CHANGED,"blocks/z.json");long revision=small.revision(),baseline=small.saveRevision();var writes=new AtomicInteger();
        try{small.save(root,(base,path,data,fingerprint)->{if(writes.incrementAndGet()==2)throw new IOException("Injected later-file publication failure");return FileSaves.write(base,path,data,fingerprint);});throw new AssertionError();}catch(IOException expectedFailure){}
        var partialAfter=smallCache.page(small,CHANGED,0);check(small.dirty() && small.revision()==revision && small.saveRevision()>baseline && partialAfter.request()!=partialBefore.request() && partialAfter.treeGeneration()!=partialBefore.treeGeneration() && paths(partialAfter).equals(paths(partialBefore)),"partial Save baseline invalidates changed-only identity even with conservative membership and dirty flags");
        var allBytes=new LinkedHashMap<String,byte[]>();for(String path:small.paths())allBytes.put(path,small.read(path));int retainedUndo=small.undoCount();small.saveCopy(temp.resolve("resource-browser-copy"));small.exportZip(temp.resolve("resource-browser.zip"));small.saveAs(temp.resolve("resource-browser-as"));check(smallCache.page(small,CHANGED,0).rows().isEmpty(),"Save As refreshes changed-only membership");
        for(var reopened:List.of(PackWorkspace.open(temp.resolve("resource-browser-copy")),PackWorkspace.importZip(temp.resolve("resource-browser.zip")),PackWorkspace.open(temp.resolve("resource-browser-as"))))for(String path:allBytes.keySet())check(Arrays.equals(reopened.read(path),allBytes.get(path)),"exact Save/Copy/As/ZIP bytes");check(small.undoCount()==retainedUndo,"storage keeps applied history");
        var other=PackWorkspace.newPack(Map.of("objects/only.iob",new byte[]{1}));check(paths(cache.page(other,ALL,0)).equals(List.of("objects")) && paths(cache.reveal(other,ALL,"objects/only.iob")).equals(List.of("objects","objects/only.iob")),"equal-revision owner isolation resets expansions");var beforeClear=cache.page(other,ALL,0);cache.clear();check(cache.page(other,ALL,0)!=beforeClear && paths(cache.page(other,ALL,0)).equals(List.of("objects")),"Clear releases tree/page/expansion/owner references");
        System.out.println("PASS: complete bounded visible resource hierarchy pages with one immutable 200-row result, folder-first ordering and full literal/family/changed-only filters, all 650 late files and 235 nested opaque assets reachable, explicit empty folders and maximum-depth Unicode/hash paths, selected-resource ancestor reveal and exact global page, expansion/collapse and stale-folder pruning, cached path-only tree with byte/Undo/Redo/Save/partial-Save/Save-As marker and membership refresh, owner/Clear isolation, draft-guarded late-page navigation and exact unknown/opaque Save/Copy/As/ZIP; no payload decoding or native previews");
    }
}
